package com.sabyeguyz.clinic.commission; import com.sabyeguyz.clinic.course.CoursePurchase; import com.sabyeguyz.clinic.staff.Staff; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="commission_allocation_ledger") public class CommissionAllocationLedger { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="course_purchase_id") private CoursePurchase coursePurchase; @Column(name="visit_date") private LocalDate visitDate; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="case_owner_employee_id") private Staff owner; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="treating_employee_id") private Staff treating; @Column(name="gross_commission_allocation") private BigDecimal gross; @Column(name="treatment_fee_amount") private BigDecimal fee; @Column(name="owner_net_commission") private BigDecimal ownerNet; @Column(name="created_at") private Instant createdAt=Instant.now(); protected CommissionAllocationLedger(){} public CommissionAllocationLedger(CoursePurchase p,BigDecimal g,BigDecimal f,BigDecimal n,Staff o,Staff t,LocalDate d){coursePurchase=p;gross=g;fee=f;ownerNet=n;owner=o;treating=t;visitDate=d;} public Long getId(){return id;} public BigDecimal getGross(){return gross;} public BigDecimal getFee(){return fee;} public BigDecimal getOwnerNet(){return ownerNet;} public LocalDate getVisitDate(){return visitDate;}}
